import raw from '../generated/resources.json';

// Generated by `npm run scrape:resources` (dragdown.wiki, SmashWiki + Discord invite check, smasharchives).
export interface ResourceLink {
  section: string;
  label: string | null;
  url: string;
  kind: 'sheet' | 'doc' | 'video' | 'tweet' | 'link' | 'discord';
}
export interface PlayerToWatch {
  name: string;
  region: string | null;
  footage: string | null;
  footageTitle?: string;
  note: string | null;
}
export interface FighterResources {
  discords: { url: string; name: string; members: number | null }[];
  players: PlayerToWatch[];
  links: ResourceLink[];
  sources: string[];
  wiki: string | null;
  vodArchive: string | null;
}

const generated = (raw as { generatedAt: string; fighters: Record<string, FighterResources> }).fighters;

// Hand-added links, merged on top of the generated data. Only add links you've verified.
const manual: Record<string, Partial<Pick<FighterResources, 'discords' | 'links' | 'players'>>> = {
  // lucas: { links: [{ section: 'Documents', label: 'Lucas move guide', url: 'https://docs.google.com/…', kind: 'doc' }] },
};

export function resourcesFor(slug: string): FighterResources {
  const g = generated[slug] ?? { discords: [], players: [], links: [], sources: [], wiki: null, vodArchive: null };
  const m = manual[slug] ?? {};
  return {
    ...g,
    discords: [...(m.discords ?? []), ...g.discords],
    links: [...(m.links ?? []), ...g.links],
    players: [...(m.players ?? []), ...g.players],
  };
}

export const youtubeSearch = (q: string) =>
  `https://www.youtube.com/results?search_query=${encodeURIComponent(q)}`;
